#include <iostream>
#include <queue>
int main() {
    std::queue<char> q;
    q.push('A'); q.push('B'); q.push('C');
    while (!q.empty()) { std::cout << q.front(); q.pop(); }
}

#include <iostream>
#include <queue>
int main() {
    std::queue<int> q;
    q.push(1); q.push(2); q.push(3);
    q.pop();
    std::cout << q.front() << " " << q.back();
}

#include <iostream>
#include <stack>
int main() {
    std::stack<int> in, out;
    for (int x : {1, 2, 3}) in.push(x);
    while (!in.empty()) { out.push(in.top()); in.pop(); }
    std::cout << out.top();
}

#include <iostream>
#include <deque>
int main() {
    std::deque<int> d;
    d.push_back(2); d.push_front(1); d.push_back(3);
    d.pop_front();
    std::cout << d.front() << d.back();
}

#include <iostream>
#include <queue>
int main() {
    std::priority_queue<int> pq;
    int a[] = {5, 1, 9, 7, 3};
    for (int x : a) pq.push(x);
    pq.pop(); pq.pop();
    std::cout << pq.top();
}

#include <iostream>
#include <deque>
int main() {
    int a[] = {1, 3, 2, 5};
    std::deque<int> dq;
    for (int x : a) {
        while (!dq.empty() && dq.back() < x) dq.pop_back();
        dq.push_back(x);
    }
    std::cout << dq.front() << " " << dq.size();
}
